const app=document.getElementById('app');
const appCfg=window.APP_CONFIG||{};
const navGroups=[{label:'الرئيسية',items:[['dashboard','لوحة التحكم','▦'],['guide','دليل التشغيل','?']]},{label:'الإدارة',items:[['users','المستخدمون','♙'],['roles','الأدوار والصلاحيات','◆'],['employees','الموظفون','♙'],['attendance','الحضور والانصراف','◷']]},{label:'التشغيل',items:[['products','المنتجات','◇'],['inventory','المخزون','▤'],['production','الإنتاج','⚙'],['sales','المبيعات ونقطة البيع','▣'],['returns','المرتجعات والتالف','↩']]},{label:'المالية',items:[['suppliers','الموردون والمشتريات','⌁'],['treasury','الخزائن والبنوك','▥'],['expenses','المصروفات','−'],['payroll','المرتبات والسلف والحوافز','₿']]},{label:'المتابعة',items:[['reports','التقارير','▤'],['audit','سجل التدقيق','⌁'],['settings','الإعدادات','⚙']]}];
const titles=Object.fromEntries(navGroups.flatMap(g=>g.items.map(x=>[x[0],x[1]])));
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
const money=v=>`${Number(v||0).toLocaleString('ar-SD',{maximumFractionDigits:2})} ${appCfg.currency||'ج.س'}`;
const dateText=v=>v?new Intl.DateTimeFormat('ar-SD',{dateStyle:'medium',timeStyle:'short',timeZone:appCfg.timezone||'Africa/Khartoum'}).format(new Date(v)):'—';
const todayText=()=>new Intl.DateTimeFormat('ar-SD',{dateStyle:'full',timeZone:appCfg.timezone||'Africa/Khartoum'}).format(new Date());
const route=()=>location.hash.replace(/^#\/?/,'').split('?')[0]||'dashboard';
function toast(text,type='ok'){const el=document.createElement('div');el.className=`toast ${type==='error'?'error':''}`;el.textContent=text;document.getElementById('toast-region').append(el);setTimeout(()=>el.remove(),4200)}
function online(){return navigator.onLine!==false}
function queuedCount(){try{return JSON.parse(localStorage.getItem(appCfg.offlineQueueKey||'sandal_factory_offline_queue_v1')||'[]').length}catch{return 0}}
function empty(title='لا توجد بيانات',sub='ابدأ بإضافة أول سجل من الزر أعلاه.'){return`<div class="empty-state"><b>${title}</b><span>${sub}</span></div>`}
function btn(label,action,variant='primary',extra=''){return`<button class="btn btn-${variant}" data-action="${action}" ${extra}>${label}</button>`}
function pageHead(title,sub,actions=''){return`<div class="page-header"><div><div class="eyebrow">${esc(appCfg.factoryName||'مصنع الصندل للأوعية البلاستيكية')} · المدير</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="header-actions">${actions}</div></div>`}
function stat(label,value,foot,icon){return`<div class="stat-card"><div class="stat-top"><span>${label}</span><i class="stat-icon">${icon}</i></div><div class="stat-value num">${value}</div><div class="stat-foot">${foot}</div></div>`}
function loginView(){return`<main class="login-page"><section class="login-hero"><div class="brand-lockup"><div class="brand-mark">SP</div><div><strong>${esc(appCfg.factoryName)}</strong><small>الإدارة الذكية للمصنع</small></div></div><div class="login-copy"><div class="eyebrow">بوابة الإدارة</div><h1>كل عمليات المصنع، في مكان واحد.</h1><p>المبيعات والمخزون والإنتاج والموظفون والمالية، مترابطة بوضوح من أول يوم تشغيل.</p></div><div class="login-foot">نظام داخلي آمن · يعمل على الهاتف والكمبيوتر</div></section><section class="login-side"><form id="login-form" class="login-card"><h2>تسجيل الدخول</h2><p class="sub">أدخل بياناتك للوصول إلى الأقسام المصرح بها.</p><label class="field">البريد الإلكتروني<input type="email" name="email" placeholder="name@factory.com" autocomplete="username" required></label><label class="field">كلمة المرور<input type="password" name="password" placeholder="••••••••" autocomplete="current-password" required></label><button class="btn btn-primary btn-wide">دخول إلى النظام</button><div id="login-error" class="error"></div></form></section></main>`}
function sidebar(){return`<aside id="sidebar" class="sidebar"><div class="sidebar-brand"><div class="brand-mark">SP</div><div><strong>مصنع الصندل</strong><small>إدارة المصنع الذكية</small></div></div><nav>${navGroups.map(g=>`<div class="nav-group"><div class="nav-label">${g.label}</div><div class="nav-list">${g.items.map(([id,label,icon])=>`<a class="nav-item ${route()===id?'active':''}" href="#/${id}"><span class="nav-icon">${icon}</span><span>${label}</span></a>`).join('')}</div></div>`).join('')}</nav><div class="sidebar-bottom"><div class="connection"><i class="dot"></i><span id="connection-text">${online()?'النظام متصل وآمن':'وضع أوفلاين'}</span></div><div class="connection"><span>عمليات معلقة: <b id="queue-count">${queuedCount()}</b></span></div></div></aside>`}
function topbar(){const p=window.currentProfile||{};return`<header class="topbar"><div class="topbar-left"><button class="menu-btn" data-action="menu" aria-label="القائمة">☰</button><div><div class="topbar-title">${esc(titles[route()]||'لوحة التحكم')}</div><div class="topbar-date">${todayText()}</div></div></div><div class="profile-box"><div><strong>${esc(p.full_name||appCfg.managerName||'المدير')}</strong><small>${esc(p.role_name||'المدير')}</small></div><div class="avatar">${esc((p.full_name||'ع').slice(0,1))}</div><button class="btn btn-outline btn-sm" data-action="logout">خروج</button></div></header>`}
async function count(table){try{return(await dbSelect(table,'id',{limit:1})).length}catch{return 0}}
async function dashboard(){const [products,employees]=await Promise.all([count('products'),count('employees')]);return`${pageHead('لوحة التحكم','ملخص واضح لحركة المصنع والمال والمخزون خلال اليوم',btn('دليل التشغيل','go-guide','soft'))}<section class="stats-grid">${stat('المبيعات اليوم',money(0),'من الفواتير المعتمدة','▣')}${stat('المصروفات اليوم',money(0),'من الحركات المعتمدة','−')}${stat('الأصناف المسجلة',products,'بيانات فعلية من Supabase','◇')}${stat('العاملون النشطون',employees,'ملفات الموظفين','♙')}</section><div class="dashboard-grid"><section class="panel profit-card"><div class="panel-head"><div><h2 class="panel-title">الوضع المالي المختصر</h2><p class="panel-sub">لا يتم احتساب أي رقم إلا من العمليات المعتمدة</p></div><span class="badge">متصل</span></div><div class="profit-number num">${money(0)}</div><div class="profit-caption">صافي الربح بعد المصروفات · يبدأ الحساب بعد تسجيل العمليات</div><div class="progress"><i></i></div><div class="split"><div class="mini-stat"><span>المبيعات</span><strong class="num">${money(0)}</strong><small>اليوم</small></div><div class="mini-stat"><span>المصروفات</span><strong class="num">${money(0)}</strong><small>اليوم</small></div></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">ابدأ من هنا</h2><p class="panel-sub">ترتيب عملي لتجهيز المصنع</p></div></div><div class="quick-actions"><a class="quick-action" href="#/products"><i>◇</i><div><strong>عرّف المنتجات</strong><small>اسم، وحدة، تكلفة وسعر</small></div></a><a class="quick-action" href="#/treasury"><i>▥</i><div><strong>جهّز الخزائن</strong><small>أرصدة وحسابات الدفع</small></div></a><a class="quick-action" href="#/employees"><i>♙</i><div><strong>سجّل العمال</strong><small>ملف وحضور ومرتبات</small></div></a><a class="quick-action" href="#/sales"><i>▣</i><div><strong>ابدأ البيع</strong><small>فاتورة مرتبطة بالمخزون</small></div></a></div></section></div><section class="panel table-panel">${empty('لا توجد عمليات اليوم','ستظهر هنا آخر المبيعات والمصروفات والحركات المالية بعد إدخالها واعتمادها.')}</section>`}
function guide(){return`${pageHead('دليل التشغيل','كيف تعمل المنظومة؟','خطوات واضحة للعامل والمدير دون إدخال مكرر')}<section class="section-grid"><div class="section-card"><div class="section-icon">⚙</div><h3>الإعداد</h3><p>أنشئ الوحدات والتصنيفات والخزائن والبنوك والورديات مرة واحدة.</p></div><div class="section-card"><div class="section-icon">◇</div><h3>المنتجات</h3><p>عرّف المنتج بالتكلفة وسعر البيع، وسيظهر تلقائيًا في كل الأقسام.</p></div><div class="section-card"><div class="section-icon">▤</div><h3>التشغيل</h3><p>سجّل شراء الخام والإنتاج والوارد والصادر من خلال حركات موثقة.</p></div><div class="section-card"><div class="section-icon">▣</div><h3>البيع</h3><p>أنشئ فاتورة واعتمدها لتحديث المخزون والخزنة أو البنك.</p></div><div class="section-card"><div class="section-icon">♙</div><h3>الموظفون</h3><p>سجّل العامل ثم استخدم الحضور والسلف والحوافز وكشف المرتب.</p></div><div class="section-card"><div class="section-icon">⌁</div><h3>المتابعة</h3><p>راجع التقارير والتدقيق واعتمد أو ألغ العمليات حسب الصلاحية.</p></div></section>`}
const moduleInfo={users:['إدارة المستخدمين','حساب مستقل لكل مستخدم وصلاحياته وسجل نشاطه.','إضافة مستخدم'],roles:['الأدوار والصلاحيات','تحكم دقيق في العرض والإضافة والتعديل والاعتماد والتقارير.','إدارة الصلاحيات'],employees:['الموظفون','ملف العامل والقسم والوظيفة والوردية والأجر والحالة.','إضافة موظف'],attendance:['الحضور والانصراف','زر واحد لكل عامل يسجل الوقت ويحسب الساعات تلقائيًا.','تسجيل الحضور'],products:['المنتجات','تعريف المنتج مرة واحدة ليظهر في البيع والإنتاج والمخزون والمرتجعات.','إضافة منتج'],inventory:['المخزون','وارد وصادر وتحويل وجرد، والرصيد يحسب من الحركات المعتمدة.','حركة وارد / صادر'],production:['الإنتاج','أوامر إنتاج للطلبية أو المخزون أو إعادة التصنيع والتدوير.','أمر إنتاج'],sales:['المبيعات ونقطة البيع','فواتير بيع ومبدئية ومفتوحة، دفع جزئي وربط فوري بالمخزون والمال.','فاتورة بيع'],returns:['المرتجعات والتالف','مرتجع مربوط بفاتورة أصلية مع صالح وفحص وتالف.','إضافة مرتجع'],suppliers:['الموردون والمشتريات','موردون وشراء متعدد البنود ومدفوع ومتأخر.','مورد جديد'],treasury:['الخزائن والبنوك','خزائن وحسابات وتحويلات وحركات مالية مرتبطة بكل عملية.','حركة مالية'],expenses:['المصروفات','تسجيل المصروف واعتماده وربطه بالقسم والخزنة أو البنك.','منصرف جديد'],payroll:['المرتبات والسلف والحوافز','كشف عامل واضح يضم الأساسي والحضور والحافز والسلفة والدفع.','كشف راتب'],reports:['التقارير','تقارير المبيعات والمشتريات والمخزون والمال والمرتبات حسب الفترة.','تقرير جديد'],audit:['سجل التدقيق','كل إنشاء وتعديل واعتماد وإلغاء باسم المستخدم والتاريخ والوقت.','مراجعة السجل'],settings:['الإعدادات','هوية المصنع والضريبة والعملات والحساب والمدير وإعادة الضبط الحساسة.','فتح الإعدادات']};
async function productsPage(){const [rows,cats,units]=await Promise.all([dbSelect('products','id,product_number,name,category_name,unit_name,cost_price,sale_price,minimum_stock,is_active,notes,custom_fields,created_at,updated_at',{order:{column:'name'},limit:300}),dbSelect('product_categories','id,name',{order:{column:'name'},limit:200}),dbSelect('units','id,name',{order:{column:'name'},limit:200})]);const catsList=cats.map(x=>`<option value="${esc(x.name)}"></option>`).join(''),unitsList=units.map(x=>`<option value="${esc(x.name)}"></option>`).join('');const rowsHtml=rows.map(r=>`<tr data-search-text="${esc(`${r.name} ${r.product_number} ${r.category_name||''}`)}"><td><span class="badge blue">${esc(r.product_number)}</span></td><td><strong>${esc(r.name)}</strong></td><td>${esc(r.category_name||'—')}</td><td>${esc(r.unit_name||'—')}</td><td class="num">${money(r.cost_price)}</td><td class="num">${money(r.sale_price)}</td><td class="num">${r.minimum_stock||0}</td><td><span class="badge ${r.is_active?'':'danger'}">${r.is_active?'نشط':'غير نشط'}</span></td><td><div class="table-tools">${btn('عرض','product-view','soft',`data-id="${esc(r.id)}"`)}${btn('تعديل','product-edit','outline',`data-id="${esc(r.id)}"`)}${btn(r.is_active?'تعطيل':'تفعيل','product-toggle',r.is_active?'danger':'soft',`data-id="${esc(r.id)}" data-active="${!r.is_active}`)}</div></td></tr>`).join('');const modal=productModal();return`${pageHead('المنتجات','عرّف المنتج مرة واحدة ليظهر تلقائيًا في البيع والمخزون والإنتاج والمرتجعات',btn('إضافة منتج','product-new'))}<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">دليل المنتجات</h2><p class="panel-sub">لا يوجد باركود؛ البحث باسم المنتج أو رقمه الداخلي فقط.</p></div><input class="search" id="product-search" placeholder="ابحث باسم المنتج"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>اسم المنتج</th><th>التصنيف</th><th>الوحدة</th><th>التكلفة</th><th>سعر البيع</th><th>الحد الأدنى</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody id="products-body">${rowsHtml||`<tr><td colspan="9">${empty('لا توجد منتجات بعد','أضف أول منتج باسم واضح؛ ثم سيظهر تلقائيًا في الأقسام المرتبطة.')}</td></tr>`}</tbody></table></div></section>${modal}<datalist id="product-categories">${catsList}</datalist><datalist id="product-units">${unitsList}</datalist>`}
function productModal(){return`<div id="product-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2 id="product-modal-title">إضافة منتج</h2><p class="panel-sub">التصنيف والوحدة حقول حرة، والقيم الجديدة تحفظ تلقائيًا.</p></div><button class="close" data-action="modal-close" aria-label="إغلاق">×</button></div><form id="product-form" class="form-grid"><input type="hidden" name="id"><label class="field full">اسم المنتج *<input name="name" required placeholder="مثال: أكياس بلاستيكية"></label><label class="field">التصنيف<input name="category" list="product-categories" placeholder="مثال: منتجات نهائية"></label><label class="field">الوحدة<input name="unit" list="product-units" placeholder="مثال: قطعة أو كرتونة"></label><label class="field">تكلفة الوحدة<input name="cost_price" type="number" min="0" step="0.01" placeholder="مثال: 250"></label><label class="field">سعر البيع<input name="sale_price" type="number" min="0" step="0.01" placeholder="مثال: 350"></label><label class="field">الحد الأدنى للمخزون<input name="minimum_stock" type="number" min="0" step="0.001" placeholder="مثال: 100"></label><label class="field full">الملاحظات<textarea name="notes" rows="2" placeholder="مثال: مقاس كبير، لون أزرق..."></textarea></label><div class="full"><div class="panel-head"><div><h3 class="panel-title">حقول إضافية</h3><p class="panel-sub">أضف تاريخ التصنيع أو المورد أو اللون عند الحاجة فقط.</p></div><button type="button" class="btn btn-soft btn-sm" data-action="product-add-field">+ إضافة حقل</button></div><div id="product-custom-fields"></div></div><div class="full form-footer"><button class="btn btn-primary">حفظ المنتج</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div>`}
function showModal(id){document.getElementById(id)?.classList.remove('hidden')}
function hideModal(id){document.getElementById(id)?.classList.add('hidden')}
function customFieldsFromForm(form){const out={};form.querySelectorAll('[data-custom-key]').forEach(row=>{const k=row.querySelector('[data-custom-key]')?.value?.trim(),v=row.querySelector('[data-custom-value]')?.value?.trim();if(k&&v)out[k]=v});return out}
function addCustomField(key='',value=''){const box=document.getElementById('product-custom-fields');if(!box)return;const row=document.createElement('div');row.className='form-grid custom-row';row.innerHTML=`<label class="field">اسم الحقل<input data-custom-key value="${esc(key)}" placeholder="مثال: اللون"></label><label class="field">القيمة<input data-custom-value value="${esc(value)}" placeholder="مثال: أزرق"></label>`;box.append(row)}
async function openProduct(id){const form=document.getElementById('product-form');if(!form)return;const title=document.getElementById('product-modal-title');form.reset();form.querySelector('[name="id"]').value='';document.getElementById('product-custom-fields').innerHTML='';if(id){try{const r=(await dbSelect('products','id,name,category_name,unit_name,cost_price,sale_price,minimum_stock,notes,custom_fields',{eq:{id},limit:1}))[0];if(!r)return;title.textContent='تعديل المنتج';Object.entries({id:r.id,name:r.name,category:r.category_name||'',unit:r.unit_name||'',cost_price:r.cost_price,sale_price:r.sale_price,minimum_stock:r.minimum_stock,notes:r.notes||''}).forEach(([k,v])=>form.querySelector(`[name="${k}"]`).value=v??'');Object.entries(r.custom_fields||{}).forEach(([k,v])=>addCustomField(k,v))}catch(e){toast(friendlyError(e),'error');return}}else{title.textContent='إضافة منتج'}showModal('product-modal');form.querySelector('[name="name"]').focus()}
function productDetails(id){const row=document.querySelector(`[data-search-text] [data-id="${id}"]`);const tr=[...document.querySelectorAll('#products-body tr')].find(x=>x.querySelector(`[data-id="${id}"]`));if(!tr)return;const cells=[...tr.querySelectorAll('td')].map(x=>x.innerText.trim());const modal=document.createElement('div');modal.className='modal-backdrop';modal.id='product-detail-modal';modal.innerHTML=`<section class="modal"><div class="modal-head"><h2>تفاصيل المنتج</h2><button class="close" data-action="modal-close">×</button></div><div class="metric-line"><span>الرقم</span><strong>${esc(cells[0])}</strong></div><div class="metric-line"><span>الاسم</span><strong>${esc(cells[1])}</strong></div><div class="metric-line"><span>التصنيف</span><strong>${esc(cells[2])}</strong></div><div class="metric-line"><span>الوحدة</span><strong>${esc(cells[3])}</strong></div><div class="metric-line"><span>التكلفة</span><strong>${esc(cells[4])}</strong></div><div class="metric-line"><span>سعر البيع</span><strong>${esc(cells[5])}</strong></div><div class="metric-line"><span>الحد الأدنى</span><strong>${esc(cells[6])}</strong></div></section>`;document.body.append(modal)}

async function salesPage(){const [products,warehouses,sales,cash,banks]=await Promise.all([dbSelect('products','id,product_number,name,unit_name,sale_price,cost_price,is_active',{eq:{is_active:true},order:{column:'name'},limit:300}),dbSelect('warehouses','id,name,warehouse_number,is_active',{eq:{is_active:true},order:{column:'name'},limit:100}),dbSelect('sales','id,invoice_number,invoice_type,customer_name,total,paid_amount,remaining_amount,payment_method,status,sold_at',{order:{column:'sold_at',ascending:false},limit:200}),dbSelect('cash_registers','id,name',{eq:{is_active:true},order:{column:'name'},limit:100}),dbSelect('banks','id,name',{eq:{is_active:true},order:{column:'name'},limit:100})]);const pOpts=products.map(p=>`<option value="${esc(p.id)}" data-price="${p.sale_price}">${esc(p.name)} · ${esc(p.product_number)} · ${money(p.sale_price)}</option>`).join('');const wOpts=warehouses.map(w=>`<option value="${esc(w.id)}">${esc(w.name)} · ${esc(w.warehouse_number)}</option>`).join(''),cOpts=cash.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join(''),bOpts=banks.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join(''),saleRows=sales.map(x=>`<tr><td>${esc(x.invoice_number)}</td><td>${esc(x.customer_name||'عميل عادي')}</td><td class="num">${money(x.total)}</td><td class="num">${money(x.paid_amount)}</td><td class="num">${money(x.remaining_amount)}</td><td><span class="badge ${x.status==='approved'?'':'warn'}">${x.status==='approved'?'معتمدة':'مسودة'}</span></td><td>${x.status==='draft'?btn('اعتماد','sale-approve','soft',`data-id="${esc(x.id)}"`):(Number(x.remaining_amount||0)>0?btn('دفعة','sale-payment','soft',`data-id="${esc(x.id)}" data-name="${esc(x.invoice_number)}" data-remaining="${x.remaining_amount}"`):'مسدد')}${btn('طباعة','sale-print','soft',`data-number="${esc(x.invoice_number)}" data-customer="${esc(x.customer_name||'عميل عادي')}" data-total="${x.total||0}" data-paid="${x.paid_amount||0}" data-remaining="${x.remaining_amount||0}"`)}${btn('واتساب','sale-whatsapp','soft',`data-number="${esc(x.invoice_number)}" data-total="${x.total||0}" data-remaining="${x.remaining_amount||0}"`)}</td></tr>`).join('');return`${pageHead('المبيعات ونقطة البيع','فاتورة واضحة مرتبطة بالمخزون والخزنة أو البنك، مع دعم المسودة والدفع الجزئي',btn('فاتورة جديدة','sale-new'))}<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">فواتير المبيعات</h2><p class="panel-sub">لا يتم خصم المخزون أو إضافة المال إلا بعد الاعتماد.</p></div><input class="search" id="sales-search" placeholder="ابحث برقم الفاتورة أو اسم العميل"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الفاتورة</th><th>العميل</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>${saleRows||`<tr><td colspan="7">${empty('لا توجد فواتير بعد','أنشئ فاتورة جديدة، ثم اختر المنتج والمخزن وطريقة الدفع.')}</td></tr>`}</tbody></table></div></section><div id="sale-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>فاتورة مبيعات جديدة</h2><p class="panel-sub">اكتب الضروري فقط؛ الإجمالي والخصم والضريبة تحسب تلقائيًا.</p></div><button class="close" data-action="modal-close">×</button></div><form id="sale-form"><div class="form-grid"><label class="field">نوع الفاتورة<select name="invoice_type"><option value="sale">بيع نهائي</option><option value="proforma">مبدئية</option><option value="open">مفتوحة</option></select></label><label class="field">العميل<input name="customer_name" placeholder="عميل عادي أو اسم العميل"></label><label class="field">المخزن<select name="warehouse_id" required><option value="">اختر المخزن</option>${wOpts}</select></label><label class="field">طريقة الخصم<select name="discount_type"><option value="amount">مبلغ</option><option value="percent">نسبة مئوية</option></select></label><label class="field">قيمة الخصم<input name="discount_value" type="number" min="0" step="0.01" value="0" placeholder="مثال: 500"></label><label class="field">المصنعية<input name="crafting_fee" type="number" min="0" step="0.01" value="0" placeholder="مثال: 1000"></label><label class="field"><span class="check-field"><input name="vat_enabled" type="checkbox"> تفعيل ضريبة القيمة المضافة</span></label><label class="field">نسبة الضريبة %<input name="vat_rate" type="number" min="0" step="0.01" value="0" placeholder="مثال: 15"></label></div><div class="panel-head" style="margin-top:14px"><div><h3 class="panel-title">بنود الفاتورة</h3><p class="panel-sub">يمكن إضافة أكثر من منتج، ويتجمع المنتج المتكرر في سطر واحد.</p></div><button type="button" class="btn btn-soft btn-sm" data-action="sale-add-line">+ إضافة منتج</button></div><div id="sale-lines"></div><div class="panel" style="margin-top:12px;background:#fbfdfd"><div class="metric-line"><span>المجموع قبل الخصم</span><strong id="sale-subtotal">0</strong></div><div class="metric-line"><span>الضريبة</span><strong id="sale-vat">0</strong></div><div class="metric-line"><span>الإجمالي</span><strong id="sale-total">0</strong></div></div><div class="panel-head" style="margin-top:14px"><div><h3 class="panel-title">الدفع</h3><p class="panel-sub">يمكن تركه صفرًا للمسودة أو إدخال دفعة جزئية.</p></div></div><div class="form-grid"><label class="field">المبلغ المدفوع<input name="paid_amount" type="number" min="0" step="0.01" value="0" placeholder="مثال: 10000"></label><label class="field">طريقة الدفع<select name="payment_method"><option value="cash">كاش</option><option value="bank">بنك</option><option value="partial_cash">دفعة نقدية جزئية</option><option value="partial_bank">دفعة بنكية جزئية</option></select></label><label class="field">الخزنة<select name="cash_register_id"><option value="">اختر الخزنة عند الكاش</option>${cOpts}</select></label><label class="field">البنك<select name="bank_id"><option value="">اختر البنك عند البنك</option>${bOpts}</select></label><label class="field full">ملاحظات<textarea name="notes" rows="2" placeholder="مثال: تسليم اليوم أو ملاحظة للعميل"></textarea></label></div><div class="full form-footer"><button class="btn btn-primary">حفظ الفاتورة</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div><template id="sale-line-template"><div class="sale-line panel" style="margin-bottom:10px"><div class="form-grid"><label class="field full">المنتج<select name="product_id" data-sale-product required><option value="">اختر المنتج</option>${pOpts}</select></label><label class="field">الكمية<input name="quantity" data-sale-qty type="number" min="0.001" step="0.001" value="1" required></label><label class="field">سعر البيع<input name="unit_price" data-sale-price type="number" min="0" step="0.01" value="0" required></label></div><button type="button" class="btn btn-danger btn-sm" data-action="sale-remove-line">حذف السطر</button></div></template><div id="sale-payment-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>إضافة دفعة للفاتورة</h2><p class="panel-sub">الدفعة تدخل الحساب وتحدّث المتبقي مرة واحدة.</p></div><button class="close" data-action="modal-close">×</button></div><form id="sale-payment-form" class="form-grid"><input type="hidden" name="sale_id"><label class="field full">الفاتورة<input name="invoice" readonly></label><label class="field">المتبقي<input name="remaining" readonly></label><label class="field">قيمة الدفعة<input name="amount" type="number" min="0.01" step="0.01" required placeholder="مثال: 100000"></label><label class="field">طريقة الدفع<select name="method"><option value="cash">كاش</option><option value="bank">بنك</option></select></label><label class="field">الخزنة<select name="cash_id"><option value="">اختر الخزنة</option>${cOpts}</select></label><label class="field">البنك<select name="bank_id"><option value="">اختر البنك</option>${bOpts}</select></label><label class="field full">المرجع<input name="reference" placeholder="رقم إيصال أو تحويل اختياري"></label><div class="full form-footer"><button class="btn btn-primary">حفظ الدفعة</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div>`}
function addSaleLine(){const t=document.getElementById('sale-line-template'),box=document.getElementById('sale-lines');if(!t||!box)return;box.append(t.content.cloneNode(true));updateSaleTotals()}
function updateSaleTotals(){const f=document.getElementById('sale-form');if(!f)return;let sub=0;f.querySelectorAll('.sale-line').forEach(l=>sub+=Number(l.querySelector('[data-sale-qty]')?.value||0)*Number(l.querySelector('[data-sale-price]')?.value||0));const typ=f.querySelector('[name="discount_type"]')?.value||'amount',value=Number(f.querySelector('[name="discount_value"]')?.value||0),discount=typ==='percent'?sub*Math.min(value,100)/100:Math.min(value,sub),craft=Number(f.querySelector('[name="crafting_fee"]')?.value||0),vat=f.querySelector('[name="vat_enabled"]')?.checked?Math.max(sub-discount+craft,0)*Number(f.querySelector('[name="vat_rate"]')?.value||0)/100:0,total=Math.max(sub-discount+craft+vat,0);[['sale-subtotal',sub],['sale-vat',vat],['sale-total',total]].forEach(([id,v])=>{const x=document.getElementById(id);if(x)x.textContent=money(v)});return total}
function openSale(){const f=document.getElementById('sale-form');if(!f)return;f.reset();document.getElementById('sale-lines').innerHTML='';addSaleLine();document.getElementById('sale-modal').classList.remove('hidden')}
function openSalePayment(el){const f=document.getElementById('sale-payment-form');if(f){f.reset();f.sale_id.value=el.dataset.id;f.invoice.value=el.dataset.name;f.remaining.value=el.dataset.remaining}document.getElementById('sale-payment-modal')?.classList.remove('hidden')}
function printSale(el){const w=window.open('','_blank','width=420,height=650');if(!w){toast('اسمح بالنوافذ المنبثقة للطباعة','error');return}w.document.write(`<!doctype html><html dir="rtl"><head><meta charset="utf-8"><title>فاتورة ${esc(el.dataset.number)}</title><style>body{font-family:Arial;padding:24px;line-height:1.8}h1{text-align:center;font-size:22px}hr{border:0;border-top:1px solid #ddd}.row{display:flex;justify-content:space-between;margin:8px 0}.total{font-weight:700;font-size:18px}</style></head><body><h1>${esc(appCfg.factoryName)}</h1><p>فاتورة مبيعات: ${esc(el.dataset.number)}</p><p>العميل: ${esc(el.dataset.customer)}</p><hr><div class="row total"><span>الإجمالي</span><span>${money(el.dataset.total)}</span></div><div class="row"><span>المدفوع</span><span>${money(el.dataset.paid)}</span></div><div class="row"><span>المتبقي</span><span>${money(el.dataset.remaining)}</span></div><hr><p>شكرًا لتعاملكم معنا.</p></body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),150)}
function whatsappSale(el){const text=encodeURIComponent(`فاتورة ${el.dataset.number} من ${appCfg.factoryName}\nالإجمالي: ${money(el.dataset.total)}\nالمتبقي: ${money(el.dataset.remaining)}`);window.open('https://wa.me/?text='+text,'_blank')}

async function inventoryPage(){const [products,warehouses,moves]=await Promise.all([dbSelect('products','id,product_number,name,unit_name,cost_price,is_active',{eq:{is_active:true},order:{column:'name'},limit:300}),dbSelect('warehouses','id,name,warehouse_number,warehouse_type,is_active',{eq:{is_active:true},order:{column:'name'},limit:100}),dbSelect('stock_movements','id,movement_number,direction,source_type,status,movement_date,notes,created_at',{order:{column:'created_at',ascending:false},limit:100})]);const pOpts=products.map(p=>`<option value="${esc(p.id)}" data-unit="${esc(p.unit_name||'')}">${esc(p.name)} · ${esc(p.product_number)}</option>`).join(''),wOpts=warehouses.map(w=>`<option value="${esc(w.id)}">${esc(w.name)} · ${esc(w.warehouse_number)}</option>`).join('');const moveRows=moves.map(m=>`<tr><td><span class="badge blue">${esc(m.movement_number)}</span></td><td>${m.direction==='in'?'وارد':m.direction==='out'?'صادر':'تحويل'}</td><td>${esc(m.source_type)}</td><td><span class="badge ${m.status==='approved'?'':'warn'}">${m.status==='approved'?'معتمد':'مسودة'}</span></td><td>${dateText(m.movement_date||m.created_at)}</td><td>${esc(m.notes||'—')}</td><td>${m.status==='draft'?btn('اعتماد','stock-approve','soft',`data-id="${esc(m.id)}"`):'—'}</td></tr>`).join('');return`${pageHead('المخزون','الرصيد الحقيقي من الحركات المعتمدة، مع فصل الخام والمنتجات الجاهزة',btn('مخزن جديد','warehouse-new','soft')+btn('حركة جديدة','stock-new'))}<section class="stats-grid">${stat('المخازن النشطة',warehouses.length,'مواقع التشغيل','▤')}${stat('حركات مسجلة',moves.length,'معتمدة ومسودات','↕')}${stat('المنتجات المتاحة',products.length,'مرتبطة بالمنتجات','◇')}${stat('الرصيد اليدوي','ممنوع','الحساب من الحركة فقط','✓')}</section><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">سجل حركات المخزون</h2><p class="panel-sub">الوارد والصادر والتحويل لا يغير الرصيد إلا بعد الاعتماد.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>رقم الحركة</th><th>النوع</th><th>المصدر</th><th>الحالة</th><th>التاريخ والوقت</th><th>الملاحظة</th><th>الإجراء</th></tr></thead><tbody>${moveRows||`<tr><td colspan="7">${empty('لا توجد حركات بعد','أضف مخزنًا ومنتجًا ثم سجّل أول حركة.')}</td></tr>`}</tbody></table></div></section><div id="stock-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>حركة مخزون جديدة</h2><p class="panel-sub">اختر الصنف والمكان والكمية؛ لا يمكن إخراج كمية أكبر من الرصيد.</p></div><button class="close" data-action="modal-close">×</button></div><form id="stock-form" class="form-grid"><label class="field">نوع الحركة<select name="direction"><option value="in">وارد</option><option value="out">صادر</option><option value="transfer">تحويل</option></select></label><label class="field">مصدر أو سبب العملية<input name="source_type" placeholder="مثال: شراء أو إنتاج أو استخدام داخلي"></label><label class="field full">المنتج<select name="product_id" required><option value="">اختر المنتج</option>${pOpts}</select></label><label class="field">الكمية<input name="quantity" type="number" min="0.001" step="0.001" required placeholder="مثال: 5000"></label><label class="field">الوحدة<input name="unit_name" placeholder="تظهر من المنتج" readonly></label><label class="field">من المخزن<select name="from_warehouse_id"><option value="">اختر عند الصادر أو التحويل</option>${wOpts}</select></label><label class="field">إلى المخزن<select name="to_warehouse_id"><option value="">اختر عند الوارد أو التحويل</option>${wOpts}</select></label><label class="field">تكلفة الوحدة<input name="cost_price" type="number" min="0" step="0.01" value="0" placeholder="للخام أو الوارد"></label><label class="field full">ملاحظة<textarea name="notes" rows="2" placeholder="مثال: إنتاج جديد للمخزن الرئيسي"></textarea></label><div class="full form-footer"><button class="btn btn-primary">حفظ الحركة كمسودة</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div><div id="warehouse-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>إضافة مخزن</h2><p class="panel-sub">اختر نوع المخزن حتى يظل الخام منفصلًا عن المنتج الجاهز.</p></div><button class="close" data-action="modal-close">×</button></div><form id="warehouse-form" class="form-grid"><label class="field full">اسم المخزن<input name="name" required placeholder="مثال: المخزن الرئيسي"></label><label class="field">نوع المخزن<select name="type"><option value="finished">منتجات جاهزة</option><option value="raw">مواد خام</option><option value="damaged">تالف وفحص</option><option value="production">تحت الإنتاج</option></select></label><label class="field">وصف مختصر<input name="notes" placeholder="مثال: جوار خط الإنتاج الأول"></label><div class="full form-footer"><button class="btn btn-primary">حفظ المخزن</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div>`}
function openStock(){const f=document.getElementById('stock-form');if(!f)return;f.reset();document.getElementById('stock-modal').classList.remove('hidden')}
