async function treasuryPage(){const [cash,banks,ct,bt]=await Promise.all([dbSelect('cash_registers','id,cash_number,name,opening_balance,is_active',{order:{column:'name'},limit:100}),dbSelect('banks','id,bank_number,name,account_name,masked_account,opening_balance,is_active',{order:{column:'name'},limit:100}),dbSelect('cash_transactions','id,transaction_number,direction,transaction_type,amount,transaction_at',{order:{column:'transaction_at',ascending:false},limit:20}),dbSelect('bank_transactions','id,transaction_number,direction,transaction_type,amount,transaction_at',{order:{column:'transaction_at',ascending:false},limit:20})]);const cashRows=cash.map(x=>`<tr><td>${esc(x.cash_number)}</td><td><strong>${esc(x.name)}</strong></td><td class="num">${money(x.opening_balance)}</td><td><span class="badge">${x.is_active?'نشطة':'موقوفة'}</span></td></tr>`).join(''),bankRows=banks.map(x=>`<tr><td>${esc(x.bank_number)}</td><td><strong>${esc(x.name)}</strong></td><td>${esc(x.masked_account||x.account_name||'—')}</td><td class="num">${money(x.opening_balance)}</td></tr>`).join('');return`${pageHead('الخزائن والبنوك','كل حركة مالية مرتبطة بحساب واضح، والتحويل الداخلي لا يُحسب مصروفًا',btn('حركة مالية','finance-new')+btn('تحويل داخلي','transfer-new','soft')+btn('جرد خزنة','count-new','soft'))}<section class="stats-grid">${stat('الخزائن',cash.length,'الحسابات النقدية','▥')}${stat('البنوك',banks.length,'الحسابات البنكية','▤')}${stat('حركات نقدية',ct.length,'آخر الحركات','↕')}${stat('حركات بنكية',bt.length,'آخر الحركات','↕')}</section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2 class="panel-title">الخزائن</h2><button class="btn btn-soft btn-sm" data-action="cash-new">+ خزنة</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>الخزنة</th><th>الرصيد الافتتاحي</th><th>الحالة</th></tr></thead><tbody>${cashRows||`<tr><td colspan="4">${empty('لا توجد خزائن','أنشئ الخزنة الرئيسية أو خزنة مبيعات من زر + خزنة.')}</td></tr>`}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2 class="panel-title">الحسابات البنكية</h2><button class="btn btn-soft btn-sm" data-action="bank-new">+ بنك</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>البنك</th><th>الحساب</th><th>الافتتاحي</th></tr></thead><tbody>${bankRows||`<tr><td colspan="4">${empty('لا توجد بنوك','أضف حساب البنك مع إخفاء جزء من الرقم حسب إعدادات الأمان.')}</td></tr>`}</tbody></table></div></section></div><div id="finance-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>إضافة حساب مالي</h2><p class="panel-sub">الحسابات ستظهر في الدفع والمصروفات والمرتبات.</p></div><button class="close" data-action="modal-close">×</button></div><form id="finance-form" class="form-grid"><label class="field">نوع الحساب<select name="kind"><option value="cash">خزنة نقدية</option><option value="bank">حساب بنكي</option></select></label><label class="field">اسم الحساب<input name="name" required placeholder="مثال: الخزنة الرئيسية"></label><label class="field">الرصيد الافتتاحي<input name="opening_balance" type="number" min="0" step="0.01" value="0" placeholder="مثال: 1000000"></label><label class="field">الحد المالي / آخر الأرقام<input name="extra" placeholder="مثال: 2000000 أو 1234"></label><label class="field full">اسم صاحب الحساب (للبنك)<input name="account_name" placeholder="مثال: مصنع الصندل"></label><div class="full form-footer"><button class="btn btn-primary">حفظ الحساب</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div><div id="transfer-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>تحويل داخلي</h2><p class="panel-sub">التحويل بين حسابات المصنع لا يُحسب إيرادًا أو مصروفًا.</p></div><button class="close" data-action="modal-close">×</button></div><form id="transfer-form" class="form-grid"><label class="field">من نوع<select name="from_type"><option value="cash">خزنة</option><option value="bank">بنك</option></select></label><label class="field">من الحساب<select name="from_id"><option value="">اختر الحساب</option>${cash.map(x=>`<option value="${esc(x.id)}">خزنة: ${esc(x.name)}</option>`).join()}${banks.map(x=>`<option value="${esc(x.id)}">بنك: ${esc(x.name)}</option>`).join()}</select></label><label class="field">إلى نوع<select name="to_type"><option value="cash">خزنة</option><option value="bank">بنك</option></select></label><label class="field">إلى الحساب<select name="to_id"><option value="">اختر الحساب</option>${cash.map(x=>`<option value="${esc(x.id)}">خزنة: ${esc(x.name)}</option>`).join()}${banks.map(x=>`<option value="${esc(x.id)}">بنك: ${esc(x.name)}</option>`).join()}</select></label><label class="field">المبلغ<input name="amount" type="number" min="0.01" step="0.01" required placeholder="مثال: 100000"></label><label class="field full">الملاحظة<input name="notes" placeholder="مثال: تغذية خزنة المبيعات"></label><div class="full form-footer"><button class="btn btn-primary">تنفيذ التحويل</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div><div id="count-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>جرد خزنة</h2><p class="panel-sub">يقارن النظام المبلغ الفعلي بالرصيد الدفتري ويسجل الفرق.</p></div><button class="close" data-action="modal-close">×</button></div><form id="count-form" class="form-grid"><label class="field full">الخزنة<select name="cash_id" required><option value="">اختر الخزنة</option>${cash.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join()}</select></label><label class="field">المبلغ الفعلي<input name="counted" type="number" min="0" step="0.01" required placeholder="مثال: 950000"></label><label class="field full">ملاحظات الجرد<textarea name="notes" rows="2" placeholder="مثال: جرد نهاية الوردية"></textarea></label><div class="full form-footer"><button class="btn btn-primary">حفظ الجرد</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div>`}
