async function expensesPage(){const [cash,banks,rows]=await Promise.all([dbSelect('cash_registers','id,name',{eq:{is_active:true},order:{column:'name'},limit:100}),dbSelect('banks','id,name',{eq:{is_active:true},order:{column:'name'},limit:100}),dbSelect('expenses','id,expense_number,category,amount,payment_method,status,expense_at,description',{order:{column:'expense_at',ascending:false},limit:100})]);const co=cash.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join(''),bo=banks.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join(''),trs=rows.map(x=>`<tr><td>${esc(x.expense_number)}</td><td>${esc(x.category)}</td><td class="num">${money(x.amount)}</td><td>${x.payment_method==='cash'?'كاش':'بنك'}</td><td><span class="badge ${x.status==='approved'?'':'warn'}">${x.status==='approved'?'معتمد':'مسودة'}</span></td><td>${dateText(x.expense_at)}</td><td>${x.status==='draft'?btn('اعتماد','expense-approve','soft',`data-id="${esc(x.id)}"`):'—'}</td></tr>`).join('');return`${pageHead('المصروفات','سجل المصروف، ثم اعتماده ليخصم من الخزنة أو البنك تلقائيًا',btn('منصرف جديد','expense-new'))}<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">المصروفات اليومية</h2><p class="panel-sub">وقود، كهرباء، صيانة، نقل، مشتريات صغيرة وغيرها حسب احتياج المصنع.</p></div><input class="search" id="expense-search" placeholder="ابحث بنوع المصروف أو الرقم"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>النوع</th><th>المبلغ</th><th>الدفع</th><th>الحالة</th><th>التاريخ والوقت</th><th>الإجراء</th></tr></thead><tbody>${trs||`<tr><td colspan="6">${empty('لا توجد مصروفات','أدخل المصروف من الزر أعلاه، وسيظهر في سجل الخزنة والتقارير بعد الاعتماد.')}</td></tr>`}</tbody></table></div></section><div id="expense-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>تسجيل مصروف</h2><p class="panel-sub">أدخل الضروري فقط؛ الحفظ ينشئ مسودة والاعتماد يحدث الرصيد.</p></div><button class="close" data-action="modal-close">×</button></div><form id="expense-form" class="form-grid"><label class="field">نوع المصروف<input name="category" required placeholder="مثال: وقود أو كهرباء أو صيانة"></label><label class="field">المبلغ<input name="amount" type="number" min="0.01" step="0.01" required placeholder="مثال: 150000"></label><label class="field">طريقة الدفع<select name="payment_method"><option value="cash">كاش</option><option value="bank">بنك</option></select></label><label class="field">الخزنة<select name="cash_register_id"><option value="">اختر الخزنة</option>${co}</select></label><label class="field">البنك<select name="bank_id"><option value="">اختر البنك</option>${bo}</select></label><label class="field">الجهة المستفيدة<input name="payee" placeholder="مثال: محطة الوقود"></label><label class="field">القسم المرتبط<input name="department" placeholder="مثال: الإنتاج أو الإدارة"></label><label class="field full">الوصف والملاحظات<textarea name="description" rows="2" placeholder="سبب الصرف أو رقم الإيصال"></textarea></label><div class="full form-footer"><button class="btn btn-primary">حفظ المصروف كمسودة</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div>`}
