async function employeesPage(){const rows=await dbSelect('employees','id,employee_number,full_name,phone,wage_type,base_salary,status,employment_date,created_at',{order:{column:'full_name'},limit:300});const trs=rows.map(x=>`<tr><td><span class="badge blue">${esc(x.employee_number)}</span></td><td><strong>${esc(x.full_name)}</strong></td><td>${esc(x.wage_type==='monthly'?'شهري':x.wage_type==='daily'?'يومي':x.wage_type==='hourly'?'بالساعة':'حسب الإنتاج')}</td><td class="num">${money(x.base_salary)}</td><td><span class="badge ${x.status==='active'?'':'warn'}">${x.status==='active'?'نشط':x.status==='suspended'?'موقوف':x.status==='leave'?'إجازة':'مؤرشف'}</span></td><td>${x.employment_date||'—'}</td><td>${btn('تعديل','employee-edit','soft',`data-id="${esc(x.id)}" data-name="${esc(x.full_name)}" data-phone="${esc(x.phone||'')}" data-salary="${x.base_salary||0}"`)}<select data-employee-status data-id="${esc(x.id)}"><option value="">تغيير الحالة</option><option value="active">نشط</option><option value="suspended">موقوف</option><option value="leave">إجازة</option><option value="archived">أرشيف</option></select></td></tr>`).join('');return`${pageHead('الموظفون','ملف العامل يُسجل مرة واحدة ثم يستخدم في الحضور والمرتبات والسلف والحوافز',btn('إضافة موظف','employee-new'))}<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">دليل العمال</h2><p class="panel-sub">ابحث بالاسم أو الرقم الوظيفي، ولا يحذف العامل إذا كان له تاريخ مالي أو حضور.</p></div><input class="search" id="employee-search" placeholder="ابحث باسم العامل أو الرقم"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>اسم العامل</th><th>نوع الأجر</th><th>الأجر الأساسي</th><th>الحالة</th><th>التعيين</th><th>الإجراء</th></tr></thead><tbody>${trs||`<tr><td colspan="7">${empty('لا يوجد عمال بعد','أضف العامل مرة واحدة، وستظهر بياناته في الحضور وكشف المرتب.')}</td></tr>`}</tbody></table></div></section><div id="employee-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>إضافة موظف</h2><p class="panel-sub">الاسم ونوع الأجر والراتب هي البيانات الأساسية.</p></div><button class="close" data-action="modal-close">×</button></div><form id="employee-form" class="form-grid"><label class="field full">اسم العامل *<input name="name" required placeholder="مثال: محمد أحمد"></label><label class="field">الهاتف<input name="phone" placeholder="مثال: 0912345678"></label><label class="field">القسم<input name="department" placeholder="مثال: الإنتاج"></label><label class="field">الوظيفة<input name="job" placeholder="مثال: مشغل ماكينة"></label><label class="field">الوردية<input name="shift" placeholder="مثال: الصباحية 08:00 - 16:00"></label><label class="field">تاريخ التعيين<input name="employment_date" type="date"></label><label class="field">نوع الأجر<select name="wage_type"><option value="monthly">شهري</option><option value="daily">يومي</option><option value="hourly">بالساعة</option><option value="piecework">حسب الإنتاج</option></select></label><label class="field">الأجر الأساسي<input name="base_salary" type="number" min="0" step="0.01" placeholder="مثال: 350000"></label><label class="field full">ملاحظات<textarea name="notes" rows="2" placeholder="مثال: مسؤول عن خط الإنتاج الأول"></textarea></label><div class="full form-footer"><button class="btn btn-primary">حفظ الموظف</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div><div id="employee-edit-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>تعديل ملف العامل</h2><p class="panel-sub">تغيير الراتب أو البيانات يسجل في التدقيق ولا يحذف التاريخ.</p></div><button class="close" data-action="modal-close">×</button></div><form id="employee-edit-form" class="form-grid"><input type="hidden" name="id"><label class="field full">اسم العامل<input name="name" required></label><label class="field">الهاتف<input name="phone"></label><label class="field">الأجر الأساسي<input name="salary" type="number" min="0" step="0.01" required></label><label class="field full">ملاحظات<textarea name="notes" rows="2" placeholder="سبب التعديل أو ملاحظة"></textarea></label><div class="full form-footer"><button class="btn btn-primary">حفظ التعديل</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div>`}
