function openEmployeeEdit(el){const f=document.getElementById('employee-edit-form');if(f){f.reset();f.id.value=el.dataset.id;f.name.value=el.dataset.name;f.phone.value=el.dataset.phone;f.salary.value=el.dataset.salary}document.getElementById('employee-edit-modal')?.classList.remove('hidden')}
async function attendancePage(){const employees=await dbSelect('employees','id,employee_number,full_name,status',{eq:{status:'active'},order:{column:'full_name'},limit:300});const records=await dbSelect('attendance_records','id,employee_id,work_date,check_in_at,check_out_at,working_minutes,status',{eq:{work_date:new Date().toISOString().slice(0,10)},limit:300});const by=Object.fromEntries(records.map(x=>[x.employee_id,x]));const trs=employees.map(e=>{const a=by[e.id],state=!a?'لم يحضر':!a.check_out_at?'حاضر الآن':'انصرف';return`<tr><td>${esc(e.employee_number)}</td><td><strong>${esc(e.full_name)}</strong></td><td>${state}</td><td>${a?.check_in_at?dateText(a.check_in_at):'—'}</td><td>${a?.check_out_at?dateText(a.check_out_at):'—'}</td><td class="num">${a?.working_minutes?Math.round(a.working_minutes/60*100)/100+' ساعة':'—'}</td><td>${btn(!a||!a.check_out_at?(a?'انصراف':'حضور'):'مكتمل',`attendance-toggle`,`soft`,`data-id="${esc(e.id)}" ${a&&a.check_out_at?'disabled':''}`)}</td></tr>`}).join('');return`${pageHead('الحضور والانصراف','زر واحد لكل عامل يسجل وقت الخادم ويحسب ساعات العمل تلقائيًا',btn('تحديث اليوم','attendance-refresh','soft'))}<section class="stats-grid">${stat('إجمالي النشطين',employees.length,'ملفات العاملين','♙')}${stat('حضروا اليوم',records.length,'سجلات اليوم','✓')}${stat('لم ينصرفوا',records.filter(x=>x.check_in_at&&!x.check_out_at).length,'حضور مفتوح','◷')}${stat('التاريخ',new Date().toLocaleDateString('ar-SD'),'اليوم','▦')}</section><section class="panel table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>العامل</th><th>الحالة</th><th>الحضور</th><th>الانصراف</th><th>الساعات</th><th>الإجراء</th></tr></thead><tbody>${trs||`<tr><td colspan="7">${empty('لا يوجد عمال نشطون','أضف الموظف أولًا من قسم الموظفين.')}</td></tr>`}</tbody></table></div></section>`}
async function payrollPage(){const [periods,employees,advances,incentives,cash,banks]=await Promise.all([dbSelect('payroll_periods','id,period_name,from_date,to_date,status,created_at',{order:{column:'created_at',ascending:false},limit:50}),dbSelect('employees','id,employee_number,full_name,base_salary,status',{eq:{status:'active'},order:{column:'full_name'},limit:300}),dbSelect('employee_advances','id,employee_id,amount,remaining_amount,reason,advance_date,status',{order:{column:'advance_date',ascending:false},limit:300}),dbSelect('employee_incentives','id,employee_id,amount,reason,period_start,period_end,status',{order:{column:'created_at',ascending:false},limit:300}),dbSelect('cash_registers','id,name',{eq:{is_active:true},order:{column:'name'},limit:100}),dbSelect('banks','id,name',{eq:{is_active:true},order:{column:'name'},limit:100})]);const an=Object.fromEntries(employees.map(x=>[x.id,x.full_name])),advBy=Object.fromEntries(employees.map(x=>[x.id,advances.filter(a=>a.employee_id===x.id).reduce((n,a)=>n+Number(a.remaining_amount||0),0)])),incBy=Object.fromEntries(employees.map(x=>[x.id,incentives.filter(i=>i.employee_id===x.id&&i.status==='approved').reduce((n,i)=>n+Number(i.amount||0),0)])),trs=employees.map(e=>`<tr><td>${esc(e.employee_number)}</td><td><strong>${esc(e.full_name)}</strong></td><td class="num">${money(e.base_salary)}</td><td class="num">${money(incBy[e.id]||0)}</td><td class="num">${money(advBy[e.id]||0)}</td><td>${btn('حافز','incentive-new','soft',`data-id="${esc(e.id)}" data-name="${esc(e.full_name)}"`)}</td></tr>`).join(''),cashOpts=cash.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join(''),bankOpts=banks.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');return`${pageHead('المرتبات والسلف والحوافز','كشف العامل يضم الأساسي والحوافز والسلف، والدفع يسجل في الخزنة أو البنك',btn('سلفة جديدة','advance-new','soft')+btn('إعداد فترة مرتب','payroll-new'))}<section class="stats-grid">${stat('العمال النشطون',employees.length,'يدخلون في الكشف','♙')}${stat('فترات مسجلة',periods.length,'مسودات واعتمادات','▦')}${stat('السلف القائمة',money(advances.reduce((n,x)=>n+Number(x.remaining_amount||0),0)),'المتبقي على العمال','−')}${stat('الحوافز المسجلة',money(incentives.reduce((n,x)=>n+Number(x.amount||0),0)),'حسب السجلات','+')}</section><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">ملخص العمال</h2><p class="panel-sub">يمكن منح حافز لعامل محدد، وتظهر السلفة تلقائيًا في كشف المرتب.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>العامل</th><th>الأساسي</th><th>الحوافز</th><th>السلف المتبقية</th><th>الإجراء</th></tr></thead><tbody>${trs||`<tr><td colspan="6">${empty('لا يوجد عمال','أضف العامل أولًا من قسم الموظفين.')}</td></tr>`}</tbody></table></div></section><section class="panel table-panel"><div class="panel-head"><h2 class="panel-title">فترات المرتبات</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الفترة</th><th>من</th><th>إلى</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>${periods.map(p=>`<tr><td>${esc(p.period_name)}</td><td>${p.from_date}</td><td>${p.to_date}</td><td>${esc(p.status)}</td><td>${p.status==='draft'?btn('اعتماد','payroll-approve','soft',`data-id="${esc(p.id)}"`):'—'}</td></tr>`).join('')||`<tr><td colspan="5">لا توجد فترات مرتبات بعد.</td></tr>`}</tbody></table></div></section><div id="payroll-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>إعداد فترة مرتب</h2><p class="panel-sub">يحسب النظام الأساسي والحوافز والسلف من سجلاتها.</p></div><button class="close" data-action="modal-close">×</button></div><form id="payroll-form" class="form-grid"><label class="field full">اسم الفترة<input name="name" required placeholder="مثال: مرتب أغسطس 2026"></label><label class="field">من تاريخ<input name="from" type="date" required></label><label class="field">إلى تاريخ<input name="to" type="date" required></label><div class="full form-footer"><button class="btn btn-primary">تجهيز الكشف</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div><div id="advance-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>تسجيل سلفة</h2><p class="panel-sub">السلفة تخرج من الحساب الآن وتظهر كمتبقي يُخصم من المرتب.</p></div><button class="close" data-action="modal-close">×</button></div><form id="advance-form" class="form-grid"><label class="field full">العامل<select name="employee_id" required><option value="">اختر العامل</option>${employees.map(e=>`<option value="${esc(e.id)}">${esc(e.full_name)} · ${esc(e.employee_number)}</option>`).join('')}</select></label><label class="field">المبلغ<input name="amount" type="number" min="0.01" step="0.01" required placeholder="مثال: 50000"></label><label class="field">طريقة الدفع<select name="method"><option value="cash">كاش</option><option value="bank">بنك</option></select></label><label class="field">الخزنة<select name="cash_id"><option value="">اختر الخزنة</option>${cashOpts}</select></label><label class="field">البنك<select name="bank_id"><option value="">اختر البنك</option>${bankOpts}</select></label><label class="field full">السبب<input name="reason" required placeholder="مثال: ظرف طارئ"></label><div class="full form-footer"><button class="btn btn-primary">حفظ السلفة</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div><div id="incentive-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>منح حافز</h2><p class="panel-sub">الحافز يظهر في كشف الفترة المحددة بعد اعتماده.</p></div><button class="close" data-action="modal-close">×</button></div><form id="incentive-form" class="form-grid"><input type="hidden" name="employee_id"><label class="field full">العامل<input name="employee_name" readonly></label><label class="field">قيمة الحافز<input name="amount" type="number" min="0.01" step="0.01" required placeholder="مثال: 25000"></label><label class="field">من تاريخ<input name="from" type="date"></label><label class="field">إلى تاريخ<input name="to" type="date"></label><label class="field full">السبب<input name="reason" required placeholder="مثال: إنتاجية مميزة"></label><div class="full form-footer"><button class="btn btn-primary">حفظ الحافز</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div>`}
function openPayroll(){document.getElementById('payroll-modal')?.classList.remove('hidden')}
function openAdvance(){document.getElementById('advance-modal')?.classList.remove('hidden')}
function openIncentive(el){const f=document.getElementById('incentive-form');if(f){f.employee_id.value=el.dataset.id;f.employee_name.value=el.dataset.name}document.getElementById('incentive-modal')?.classList.remove('hidden')}

async function suppliersPage(){const [suppliers,purchases,raws,products,warehouses,cash,banks]=await Promise.all([dbSelect('suppliers','id,supplier_number,name,company_name,phone,materials,is_active,created_at',{order:{column:'name'},limit:300}),dbSelect('purchases','id,purchase_number,supplier_id,total,paid_amount,remaining_amount,payment_method,status,purchase_at',{order:{column:'purchase_at',ascending:false},limit:100}),dbSelect('raw_materials','id,raw_number,name,unit_name,is_active',{eq:{is_active:true},order:{column:'name'},limit:300}),dbSelect('products','id,product_number,name,unit_name,is_active',{eq:{is_active:true},order:{column:'name'},limit:300}),dbSelect('warehouses','id,name',{eq:{is_active:true},order:{column:'name'},limit:100}),dbSelect('cash_registers','id,name',{eq:{is_active:true},order:{column:'name'},limit:100}),dbSelect('banks','id,name',{eq:{is_active:true},order:{column:'name'},limit:100})]);const sn=Object.fromEntries(suppliers.map(x=>[x.id,x.name])),trs=suppliers.map(x=>`<tr><td>${esc(x.supplier_number)}</td><td><strong>${esc(x.name)}</strong></td><td>${esc(x.company_name||'—')}</td><td>${esc(x.phone||'—')}</td><td>${esc(x.materials||'—')}</td><td><span class="badge">${x.is_active?'نشط':'غير نشط'}</span></td></tr>`).join(''),purchaseRows=purchases.map(x=>`<tr><td>${esc(x.purchase_number)}</td><td>${esc(sn[x.supplier_id]||'—')}</td><td class="num">${money(x.total)}</td><td class="num">${money(x.paid_amount)}</td><td class="num">${money(x.remaining_amount)}</td><td>${x.payment_method==='cash'?'كاش':x.payment_method==='bank'?'بنك':'آجل'}</td><td><span class="badge ${x.status==='approved'?'':'warn'}">${x.status==='approved'?'معتمد':'مسودة'}</span></td><td>${x.status==='draft'?btn('اعتماد','purchase-approve','soft',`data-id="${esc(x.id)}"`):'—'}</td></tr>`).join(''),supplierOpts=suppliers.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.supplier_number)}</option>`).join(''),rawOpts=raws.map(x=>`<option value="${esc(x.id)}" data-name="${esc(x.name)}" data-unit="${esc(x.unit_name||'')}">${esc(x.name)} · ${esc(x.raw_number)}</option>`).join(''),productOpts=products.map(x=>`<option value="${esc(x.id)}" data-name="${esc(x.name)}" data-unit="${esc(x.unit_name||'')}">${esc(x.name)} · ${esc(x.product_number)}</option>`).join(''),warehouseOpts=warehouses.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join(''),cashOpts=cash.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join(''),bankOpts=banks.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');return`${pageHead('الموردون والمشتريات','مورد واحد، شراء متعدد البنود، خام يدخل المخزون ودفع يخرج من الحساب عند الاعتماد',btn('مادة خام جديدة','raw-new','soft')+btn('مورد جديد','supplier-new')+btn('شراء خام','purchase-new'))}<div class="dashboard-grid"><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">دليل الموردين</h2><p class="panel-sub">المورد مرتبط بفاتورة الشراء والدفعات والمتبقي.</p></div><input class="search" placeholder="ابحث باسم المورد أو الهاتف"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>المورد</th><th>الشركة</th><th>الهاتف</th><th>المواد</th><th>الحالة</th></tr></thead><tbody>${trs||`<tr><td colspan="6">${empty('لا يوجد موردون','أضف موردًا حتى يظهر في المشتريات.')}</td></tr>`}</tbody></table></div></section><section class="panel table-panel"><div class="panel-head"><h2 class="panel-title">المواد الخام</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>الخامة</th><th>الوحدة</th></tr></thead><tbody>${raws.map(x=>`<tr><td>${esc(x.raw_number)}</td><td>${esc(x.name)}</td><td>${esc(x.unit_name||'—')}</td></tr>`).join('')||`<tr><td colspan="3">${empty('لا توجد خامات','أضف الخامة التي ستظهر في الشراء والإنتاج.')}</td></tr>`}</tbody></table></div></section></div><section class="panel table-panel"><div class="panel-head"><h2 class="panel-title">آخر المشتريات</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الفاتورة</th><th>المورد</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>الدفع</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>${purchaseRows||`<tr><td colspan="8">${empty('لا توجد مشتريات','أنشئ شراءً متعدد البنود ثم اعتمده لإدخال الخام وربط الدفع.')}</td></tr>`}</tbody></table></div></section><div id="supplier-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><h2>إضافة مورد</h2><button class="close" data-action="modal-close">×</button></div><form id="supplier-form" class="form-grid"><label class="field full">اسم المورد *<input name="name" required placeholder="مثال: شركة المواد الخام"></label><label class="field">الشركة<input name="company" placeholder="مثال: مصانع النيل"></label><label class="field">الهاتف<input name="phone" placeholder="مثال: 0912345678"></label><label class="field">العنوان<input name="address" placeholder="مثال: المنطقة الصناعية"></label><label class="field">المواد التي يوفرها<input name="materials" placeholder="مثال: خام بلاستيك وشوالات"></label><label class="field full">ملاحظات<textarea name="notes" rows="2" placeholder="شروط الدفع أو معلومات إضافية"></textarea></label><div class="full form-footer"><button class="btn btn-primary">حفظ المورد</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div><div id="raw-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>إضافة مادة خام</h2><p class="panel-sub">الخامة تظهر في الشراء وأوامر الإنتاج وحساب استهلاك المواد.</p></div><button class="close" data-action="modal-close">×</button></div><form id="raw-form" class="form-grid"><label class="field full">اسم المادة الخام<input name="name" required placeholder="مثال: حبيبات بلاستيك"></label><label class="field">الوحدة<input name="unit" placeholder="مثال: كيلو"></label><label class="field">الكود الداخلي<input name="code" placeholder="مثال: RAW-001"></label><label class="field full">ملاحظات<textarea name="notes" rows="2" placeholder="المواصفة أو اللون أو المورد المعتاد"></textarea></label><div class="full form-footer"><button class="btn btn-primary">حفظ الخامة</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div><div id="purchase-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>شراء خام متعدد البنود</h2><p class="panel-sub">عند الاعتماد يدخل كل بند للمخزن ويُسجل المدفوع في الخزنة أو البنك مرة واحدة.</p></div><button class="close" data-action="modal-close">×</button></div><form id="purchase-form"><div class="form-grid"><label class="field full">المورد<select name="supplier_id" required><option value="">اختر المورد</option>${supplierOpts}</select></label><label class="field">مخزن الاستلام<select name="warehouse_id" required><option value="">اختر المخزن</option>${warehouseOpts}</select></label><label class="field">رقم فاتورة المورد<input name="supplier_invoice" placeholder="اختياري"></label><label class="field">نوع الدفع<select name="payment_method"><option value="credit">آجل</option><option value="cash">كاش</option><option value="bank">بنك</option></select></label><label class="field">المبلغ المدفوع<input name="paid_amount" type="number" min="0" step="0.01" value="0" placeholder="مثال: 500000"></label><label class="field">الخصم<input name="discount" type="number" min="0" step="0.01" value="0"></label><label class="field">الخزنة<select name="cash_register_id"><option value="">اختر الخزنة</option>${cashOpts}</select></label><label class="field">البنك<select name="bank_id"><option value="">اختر البنك</option>${bankOpts}</select></label></div><div class="panel-head" style="margin-top:14px"><div><h3 class="panel-title">بنود الشراء</h3><p class="panel-sub">يمكن جمع خامات ومنتجات في نفس الفاتورة، وكل بند يدخل للمخزن المختار.</p></div><button type="button" class="btn btn-soft btn-sm" data-action="purchase-add-line">+ إضافة بند</button></div><div id="purchase-lines"></div><label class="field full">ملاحظات<textarea name="notes" rows="2" placeholder="شروط الدفع أو ملاحظات الاستلام"></textarea></label><div class="full form-footer"><button class="btn btn-primary">حفظ الشراء كمسودة</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div><template id="purchase-line-template"><div class="purchase-line panel" style="margin-bottom:10px"><div class="form-grid"><label class="field">نوع البند<select name="item_kind" data-purchase-kind><option value="raw">مادة خام</option><option value="product">منتج جاهز</option></select></label><label class="field full">المادة الخام<select name="raw_material_id" data-purchase-raw><option value="">اختر الخام</option>${rawOpts}</select></label><label class="field full">المنتج<select name="product_id" data-purchase-product><option value="">اختر المنتج</option>${productOpts}</select></label><label class="field">اسم البند<input name="item_name" data-purchase-name required placeholder="يتعبأ من الاختيار"></label><label class="field">الوحدة<input name="unit_name" data-purchase-unit placeholder="مثال: كيلو"></label><label class="field">الكمية<input name="quantity" type="number" min="0.001" step="0.001" value="1" required></label><label class="field">سعر الوحدة<input name="unit_price" type="number" min="0" step="0.01" value="0" required></label></div><button type="button" class="btn btn-danger btn-sm" data-action="purchase-remove-line">حذف البند</button></div></template>`}
function openSupplier(){document.getElementById('supplier-modal')?.classList.remove('hidden')}
function openRaw(){document.getElementById('raw-modal')?.classList.remove('hidden')}
function addPurchaseLine(){const t=document.getElementById('purchase-line-template'),box=document.getElementById('purchase-lines');if(t&&box)box.append(t.content.cloneNode(true))}
