async function returnsPage(){const [rows,sales,items]=await Promise.all([dbSelect('returns','id,return_number,sale_id,total,status,return_at,reason',{order:{column:'return_at',ascending:false},limit:100}),dbSelect('sales','id,invoice_number,customer_name,total,status,warehouse_id',{eq:{status:'approved'},order:{column:'sold_at',ascending:false},limit:200}),dbSelect('sale_items','id,sale_id,product_id,product_name,quantity,unit_price',{limit:500})]);const sn=Object.fromEntries(sales.map(x=>[x.id,x.invoice_number])),trs=rows.map(x=>`<tr><td>${esc(x.return_number)}</td><td>${esc(sn[x.sale_id]||x.sale_id||'—')}</td><td class="num">${money(x.total)}</td><td>${esc(x.status)}</td><td>${dateText(x.return_at)}</td><td>${esc(x.reason||'—')}</td><td>${x.status==='draft'?btn('اعتماد','return-approve','soft',`data-id="${esc(x.id)}"`):'—'}</td></tr>`).join(''),saleOpts=sales.map(x=>`<option value="${esc(x.id)}">${esc(x.invoice_number)} · ${esc(x.customer_name||'عميل عادي')} · ${money(x.total)}</option>`).join(''),itemOpts=items.map(x=>`<option value="${esc(x.id)}" data-sale="${esc(x.sale_id)}" data-qty="${x.quantity}" data-price="${x.unit_price}">${esc(x.product_name)} · ${x.quantity} · ${money(x.unit_price)}</option>`).join('');return`${pageHead('المرتجعات والتالف','المرتجع يبدأ من فاتورة أصلية، ويقسّم صالحًا أو تالفًا أو تحت الفحص قبل الاعتماد',btn('مرتجع جديد','return-new'))}<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">سجل المرتجعات</h2><p class="panel-sub">لا يمكن تجاوز كمية البيع، ولا يتكرر الرد المالي أو إدخال المخزون بعد الاعتماد.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>رقم المرتجع</th><th>الفاتورة</th><th>القيمة</th><th>الحالة</th><th>التاريخ والوقت</th><th>السبب</th><th>الإجراء</th></tr></thead><tbody>${trs||`<tr><td colspan="7">${empty('لا توجد مرتجعات','اختر فاتورة معتمدة ثم قسّم الكمية قبل الحفظ.')}</td></tr>`}</tbody></table></div></section><div id="return-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>مرتجع من فاتورة أصلية</h2><p class="panel-sub">يُحفظ كمسودة أولًا، ثم يعتمده صاحب الصلاحية.</p></div><button class="close" data-action="modal-close">×</button></div><form id="return-form" class="form-grid"><label class="field full">الفاتورة الأصلية<select name="sale_id" data-return-sale required><option value="">اختر فاتورة معتمدة</option>${saleOpts}</select></label><label class="field full">بند الفاتورة<select name="sale_item_id" data-return-item required><option value="">اختر البند</option>${itemOpts}</select></label><label class="field">كمية المرتجع<input name="quantity" type="number" min="0.001" step="0.001" required placeholder="لا تتجاوز كمية الفاتورة"></label><label class="field">صالح للمخزون<input name="good_quantity" type="number" min="0" step="0.001" value="0" required></label><label class="field">تالف<input name="damaged_quantity" type="number" min="0" step="0.001" value="0" required></label><label class="field">تحت الفحص<input name="inspection_quantity" type="number" min="0" step="0.001" value="0" required></label><label class="field full">سبب المرتجع<input name="reason" required placeholder="مثال: عيب تصنيع أو مقاس غير مناسب"></label><label class="field full">ملاحظات<textarea name="notes" rows="2" placeholder="ملاحظة الاستلام أو رقم طلب العميل"></textarea></label><div class="full form-footer"><button class="btn btn-primary">حفظ المرتجع كمسودة</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div>`}
