async function reportsPage(){const today=new Date().toISOString().slice(0,10);const [sales,expenses,products,employees,moves,cash]=await Promise.all([dbSelect('sales','id,total,subtotal,status,sold_at',{eq:{status:'approved'},limit:500}),dbSelect('expenses','id,amount,status,expense_at',{eq:{status:'approved'},limit:500}),dbSelect('products','id,name,sale_price,cost_price,is_active',{limit:500}),dbSelect('employees','id,full_name,status,base_salary',{limit:500}),dbSelect('stock_movements','id,direction,status,created_at',{limit:500}),dbSelect('cash_transactions','id,direction,amount,transaction_at',{limit:500})]);const salesToday=sales.filter(x=>String(x.sold_at).slice(0,10)===today),expenseToday=expenses.filter(x=>String(x.expense_at).slice(0,10)===today),sum=(a,k)=>a.reduce((n,x)=>n+Number(x[k]||0),0),salesTotal=sum(salesToday,'total'),expenseTotal=sum(expenseToday,'amount');return`${pageHead('التقارير ولوحة المدير','أرقام فعلية من العمليات المعتمدة فقط، مع فترة اليوم كبداية',btn('تحديث التقارير','reports-refresh','soft'))}<section class="stats-grid">${stat('مبيعات اليوم',money(salesTotal),'الفواتير المعتمدة','▣')}${stat('مصروفات اليوم',money(expenseTotal),'الحركات المعتمدة','−')}${stat('الأصناف النشطة',products.filter(x=>x.is_active).length,'دليل المنتجات','◇')}${stat('العمال النشطون',employees.filter(x=>x.status==='active').length,'ملفات الموظفين','♙')}</section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2 class="panel-title">ملخص الربحية</h2><span class="badge blue">اليوم</span></div><div class="metric-line"><span>الإيراد المعتمد</span><strong>${money(salesTotal)}</strong></div><div class="metric-line"><span>المصروف المعتمد</span><strong>${money(expenseTotal)}</strong></div><div class="metric-line"><span>النتيجة قبل تكلفة البضاعة</span><strong>${money(salesTotal-expenseTotal)}</strong></div><p class="panel-sub">سيتم تفصيل تكلفة البضاعة من حركة المنتج والتكلفة المسجلة عند اكتمال بيانات المخزون.</p></section><section class="panel"><div class="panel-head"><h2 class="panel-title">مؤشرات التشغيل</h2></div><div class="metric-line"><span>فواتير معتمدة</span><strong>${sales.length}</strong></div><div class="metric-line"><span>مصروفات معتمدة</span><strong>${expenses.length}</strong></div><div class="metric-line"><span>حركات المخزون</span><strong>${moves.length}</strong></div><div class="metric-line"><span>حركات الخزنة</span><strong>${cash.length}</strong></div></section></div>`}
async function usersPage(){const [rows,assignments,roles]=await Promise.all([dbSelect('profiles','id,full_name,email,is_enabled,created_at',{order:{column:'created_at',ascending:false},limit:200}),dbSelect('user_roles','user_id,role_id',{limit:500}),dbSelect('roles','id,code,name_ar',{limit:50})]);const roleNames=Object.fromEntries(roles.map(x=>[x.id,x.name_ar||x.code]));const roleBy=Object.fromEntries(assignments.map(x=>[x.user_id,roleNames[x.role_id]||'غير محدد']));const trs=rows.map(x=>`<tr><td><strong>${esc(x.full_name||'—')}</strong></td><td>${esc(x.email||'—')}</td><td><span class="badge blue">${esc(roleBy[x.id]||'غير محدد')}</span></td><td><span class="badge ${x.is_enabled?'':'warn'}">${x.is_enabled?'فعال':'معلق'}</span></td><td>${dateText(x.created_at)}</td></tr>`).join('');return`${pageHead('المستخدمون','حساب مستقل لكل مستخدم، والتعليق يحافظ على تاريخه',btn('إضافة مستخدم','user-new'))}<section class="panel table-panel"><div class="panel-head"><h2 class="panel-title">دليل المستخدمين</h2><input class="search" placeholder="ابحث باسم المستخدم أو البريد"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الاسم</th><th>البريد</th><th>الدور</th><th>الحالة</th><th>تاريخ الإنشاء</th></tr></thead><tbody>${trs||`<tr><td colspan="5">${empty('لا يوجد مستخدمون إضافيون','سيظهر كل حساب بعد إنشائه من بوابة المدير.')}</td></tr>`}</tbody></table></div></section><div id="user-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>إضافة مستخدم</h2><p class="panel-sub">كلمة المرور ترسل مباشرة إلى Auth ولا تحفظ في الواجهة.</p></div><button class="close" data-action="modal-close">×</button></div><form id="user-form" class="form-grid"><label class="field full">الاسم الكامل<input name="full_name" required placeholder="مثال: أحمد محمد"></label><label class="field full">البريد الإلكتروني<input name="email" type="email" required placeholder="name@factory.com"></label><label class="field">الدور<select name="role"><option value="finance">الحسابات</option><option value="sales">المبيعات</option><option value="inventory">المخزن والموردون</option><option value="production">الإنتاج</option><option value="manager">المدير</option></select></label><label class="field">كلمة المرور المؤقتة<input name="password" type="password" minlength="8" required placeholder="8 أحرف على الأقل"></label><div class="full form-footer"><button class="btn btn-primary">إنشاء الحساب</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div>`}
