async function rolesPage(){const [roles,perms,links,controls]=await Promise.all([dbSelect('roles','id,code,name_ar,description',{order:{column:'code'},limit:50}),dbSelect('permissions','id,code,name_ar,module',{order:{column:'module'},limit:200}),dbSelect('role_permissions','role_id,permission_id',{limit:500}),dbSelect('role_controls','role_id,data_scope,cash_visibility,can_cash_in,can_cash_out,can_transfer,can_count,can_approve,spend_limit,discount_limit,transfer_limit,adjustment_limit',{limit:50})]);const cn=Object.fromEntries(controls.map(x=>[x.role_id,x])),permBy=Object.fromEntries(perms.map(x=>[x.id,x])),linksBy={};links.forEach(x=>(linksBy[x.role_id]??=[]).push(permBy[x.permission_id]?.name_ar||permBy[x.permission_id]?.code));const cards=roles.map(r=>{const c=cn[r.id]||{},scope=c.data_scope==='own'?'بياناته فقط':c.data_scope==='department'?'بيانات القسم':'كل البيانات';return`<article class="panel role-card"><div class="panel-head"><div><span class="badge blue">${esc(r.code)}</span><h2>${esc(r.name_ar)}</h2></div><button class="btn btn-soft btn-sm" data-action="role-edit" data-id="${esc(r.id)}" data-name="${esc(r.name_ar)}" data-control='${esc(JSON.stringify(c))}'>تعديل</button></div><p>${esc(r.description||'')}</p><div class="metric-line"><span>نطاق البيانات</span><strong>${scope}</strong></div><div class="metric-line"><span>إظهار الحسابات المالية</span><strong>${c.cash_visibility?'نعم':'لا'}</strong></div><div class="permission-list">${(linksBy[r.id]||[]).slice(0,8).map(x=>`<span>${esc(x)}</span>`).join('')||'<span>لا توجد صلاحيات إضافية</span>'}</div></article>`}).join('');return`${pageHead('الأدوار والصلاحيات','تحكم في أفعال كل دور ونطاق بياناته وحدود المبالغ والحسابات المسموح بها',btn('تحديث الصلاحيات','roles-refresh','soft'))}<section class="role-grid">${cards||empty('لا توجد أدوار','أضف الأدوار من إعداد قاعدة البيانات.')}</section><section class="panel"><h2 class="panel-title">العمليات الحساسة</h2><p class="panel-sub">حذف الموظف، تغيير الراتب، اعتماد المرتبات، إلغاء الفاتورة، التسوية، تعديل الرصيد الافتتاحي، تغيير الصلاحيات وإعادة تعيين كلمة المرور تحتاج صلاحية المدير مع سبب وتدقيق.</p></section><div id="role-modal" class="modal-backdrop hidden"><section class="modal"><div class="modal-head"><div><h2>تعديل ضوابط الدور</h2><p class="panel-sub">المدير فقط يستطيع تغيير الحدود والصلاحيات المالية.</p></div><button class="close" data-action="modal-close">×</button></div><form id="role-form" class="form-grid"><input type="hidden" name="role_id"><label class="field full">الدور<input name="role_name" readonly></label><label class="field">نطاق البيانات<select name="data_scope"><option value="own">بياناته فقط</option><option value="department">بيانات القسم</option><option value="all">كل البيانات</option></select></label><label class="field"><span class="check-field"><input name="cash_visibility" type="checkbox"> عرض الحسابات المالية</span></label><label class="field"><span class="check-field"><input name="can_cash_in" type="checkbox"> وارد نقدي</span></label><label class="field"><span class="check-field"><input name="can_cash_out" type="checkbox"> صادر نقدي</span></label><label class="field"><span class="check-field"><input name="can_transfer" type="checkbox"> تحويل</span></label><label class="field"><span class="check-field"><input name="can_count" type="checkbox"> جرد</span></label><label class="field"><span class="check-field"><input name="can_approve" type="checkbox"> اعتماد</span></label><label class="field">حد الصرف<input name="spend_limit" type="number" min="0" step="0.01"></label><label class="field">حد الخصم<input name="discount_limit" type="number" min="0" step="0.01"></label><label class="field">حد التحويل<input name="transfer_limit" type="number" min="0" step="0.01"></label><label class="field">حد التسوية<input name="adjustment_limit" type="number" min="0" step="0.01"></label><div class="full form-footer"><button class="btn btn-primary">حفظ ضوابط الدور</button><button type="button" class="btn btn-outline" data-action="modal-close">إلغاء</button></div></form></section></div>`}
function openRole(el){const f=document.getElementById('role-form'),c=JSON.parse(el.dataset.control||'{}');if(f){f.reset();f.role_id.value=el.dataset.id;f.role_name.value=el.dataset.name;['data_scope','spend_limit','discount_limit','transfer_limit','adjustment_limit'].forEach(k=>{if(c[k]!==undefined&&c[k]!==null)f[k].value=c[k]});['cash_visibility','can_cash_in','can_cash_out','can_transfer','can_count','can_approve'].forEach(k=>{if(c[k]!==undefined)f[k].checked=!!c[k]})}document.getElementById('role-modal')?.classList.remove('hidden')}
async function auditPage(){const [rows,profiles]=await Promise.all([dbSelect('activity_logs','id,action,entity_type,entity_id,old_data,new_data,reason,severity,created_at,actor_id',{order:{column:'created_at',ascending:false},limit:200}),dbSelect('profiles','id,full_name,email',{limit:200})]);const names=Object.fromEntries(profiles.map(x=>[x.id,x.full_name||x.email])),json=v=>v?esc(JSON.stringify(v)):'—',trs=rows.map(x=>`<tr><td>${esc(names[x.actor_id]||'نظام')}</td><td>${esc(x.action||'—')}</td><td>${esc(x.entity_type||'—')}</td><td>${esc(x.entity_id||'—')}</td><td>${json(x.old_data)}</td><td>${json(x.new_data)}</td><td>${esc(x.reason||'—')}</td><td>${dateText(x.created_at)}</td></tr>`).join('');return`${pageHead('سجل التدقيق','كل إنشاء وتعديل واعتماد وإلغاء باسم المستخدم والقيم قبل وبعد والسبب',btn('تحديث السجل','audit-refresh','soft'))}<section class="panel table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>المنفذ</th><th>العملية</th><th>القسم</th><th>رقم السجل</th><th>قبل</th><th>بعد</th><th>السبب</th><th>التاريخ والوقت</th></tr></thead><tbody>${trs||`<tr><td colspan="8">${empty('لا توجد عمليات بعد','سيظهر هنا كل اعتماد أو تعديل أو إلغاء بعد بدء التشغيل.')}</td></tr>`}</tbody></table></div></section>`}
function modulePage(id){const [title,sub,action]=moduleInfo[id]||['قسم جديد','وحدة مترابطة ضمن النظام.','فتح القسم'];return`${pageHead(title,sub,btn(action,`${id}-action`))}<section class="panel"><div class="panel-head"><div><h2 class="panel-title">مساحة ${esc(title)}</h2><p class="panel-sub">هذه الوحدة تستخدم نفس مصدر البيانات والصلاحيات والحسابات المترابطة.</p></div><span class="badge blue">قيد البناء المرحلي</span></div>${empty('القسم جاهز للربط','سيتم تفعيل نموذجه وقاعدة بياناته في مرحلته المستقلة، ثم اختباره قبل الانتقال للقسم التالي.')}</section>`}
async function shell(){app.innerHTML=`<div class="app-shell">${sidebar()}<div class="main-area">${topbar()}<main id="view" class="content"><div class="panel">جاري تحميل القسم...</div></main></div></div>`;const id=route();try{document.getElementById('view').innerHTML=id==='dashboard'?await dashboard():id==='guide'?guide():id==='products'?await productsPage():id==='sales'?await salesPage():id==='inventory'?await inventoryPage():id==='treasury'?await treasuryPage():id==='expenses'?await expensesPage():id==='employees'?await employeesPage():id==='attendance'?await attendancePage():id==='payroll'?await payrollPage():id==='suppliers'?await suppliersPage():id==='production'?await productionPage():id==='returns'?await returnsPage():id==='settings'?await settingsPage():id==='reports'?await reportsPage():id==='users'?await usersPage():id==='roles'?await rolesPage():id==='audit'?await auditPage():modulePage(id)}catch(e){document.getElementById('view').innerHTML=`<section class="panel">${empty('تعذر تحميل القسم',String(e.message||e))}</section>`}updateConnection()}
async function render(){const session=db?(await db.auth.getSession()).data.session:null;if(!session){window.currentProfile=null;app.innerHTML=loginView();bindLogin();return}if(!window.currentProfile){try{const rows=await dbSelect('profiles','id,full_name,email,is_enabled',{eq:{id:session.user.id},limit:1});window.currentProfile=rows[0]||{full_name:session.user.email}}catch{window.currentProfile={full_name:session.user.email}}}await shell()}
function bindLogin(){document.getElementById('login-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,err=document.getElementById('login-error');if(!db){err.textContent='لم يتم إعداد اتصال Supabase.';return}err.textContent='جاري التحقق...';const d=Object.fromEntries(new FormData(f));const{error}=await db.auth.signInWithPassword({email:d.email,password:d.password});if(error){err.textContent=friendlyError(error);return}await render()})}
function updateConnection(){const text=document.getElementById('connection-text');const q=document.getElementById('queue-count');if(text)text.textContent=online()?'النظام متصل وآمن':'وضع أوفلاين';if(q)q.textContent=queuedCount()}
async function action(el){const a=el.dataset.action;if(a==='menu'){document.getElementById('sidebar')?.classList.toggle('open');return}if(a==='logout'){await db?.auth.signOut();await render();return}if(a==='go-guide'){location.hash='#/guide';return}if(a==='product-new'){openProduct();return}if(a==='product-edit'){openProduct(el.dataset.id);return}if(a==='product-view'){productDetails(el.dataset.id);return}if(a==='modal-close'){el.closest('.modal-backdrop')?.remove();return}if(a==='product-add-field'){addCustomField();return}if(a==='product-toggle'){try{await dbRpc('toggle_product',{p_id:el.dataset.id,p_active:el.dataset.active==='true'});toast(el.dataset.active==='true'?'تم تفعيل المنتج':'تم تعطيل المنتج');await render()}catch(e){toast(friendlyError(e),'error')}return}if(a==='sale-new'){openSale();return}if(a==='sale-add-line'){addSaleLine();return}if(a==='sale-remove-line'){el.closest('.sale-line')?.remove();if(!document.querySelector('.sale-line'))addSaleLine();updateSaleTotals();return}if(a==='sale-approve'){try{await dbRpc('approve_sale',{p_sale_id:el.dataset.id});toast('تم اعتماد الفاتورة وتحديث المخزون والحساب');await render()}catch(e){toast(friendlyError(e),'error')}return}if(a==='sale-payment'){openSalePayment(el);return}if(a==='sale-print'){printSale(el);return}if(a==='sale-whatsapp'){whatsappSale(el);return}if(a==='stock-new'){openStock();return}if(a==='warehouse-new'){openWarehouse();return}if(a==='stock-approve'){try{await dbRpc('approve_stock_movement',{p_movement_id:el.dataset.id});toast('تم اعتماد حركة المخزون وتحديث الرصيد');await render()}catch(e){toast(friendlyError(e),'error')}return}if(a==='finance-new'||a==='cash-new'||a==='bank-new'){openFinance();return}if(a==='transfer-new'){openTransfer();return}if(a==='count-new'){openCount();return}if(a==='expense-new'){openExpense();return}if(a==='expense-approve'){try{await dbRpc('approve_expense',{p_expense_id:el.dataset.id});toast('تم اعتماد المصروف وتسجيله في الحساب المالي');await render()}catch(e){toast(friendlyError(e),'error')}return}if(a==='employee-new'){openEmployee();return}if(a==='employee-edit'){openEmployeeEdit(el);return}if(a==='supplier-new'){openSupplier();return}if(a==='raw-new'){openRaw();return}if(a==='purchase-new'){openPurchase();return}if(a==='purchase-add-line'){addPurchaseLine();return}if(a==='purchase-remove-line'){el.closest('.purchase-line')?.remove();return}if(a==='purchase-approve'){try{await dbRpc('approve_purchase',{p_purchase_id:el.dataset.id});toast('تم اعتماد الشراء وإدخال البنود وربط المدفوع');await render()}catch(e){toast(friendlyError(e),'error')}return}if(a==='production-new'){openProduction();return}if(a==='production-approve'){openProductionApproval(el);return}if(a==='return-new'){openReturn();return}if(a==='return-approve'){try{await dbRpc('approve_return',{p_return_id:el.dataset.id});toast('تم اعتماد المرتجع وتسجيل المخزون والتالف والرد المالي');await render()}catch(e){toast(friendlyError(e),'error')}return}if(a==='attendance-toggle'){try{await dbRpc('toggle_employee_attendance',{p_employee_id:el.dataset.id});toast('تم تسجيل الحركة في الحضور');await render()}catch(e){toast(friendlyError(e),'error')}return}if(a==='attendance-refresh'){await render();return}if(a==='payroll-new'){openPayroll();return}if(a==='advance-new'){openAdvance();return}if(a==='incentive-new'){openIncentive(el);return}if(a==='payroll-approve'){try{await dbRpc('approve_payroll_period',{p_period_id:el.dataset.id});toast('تم اعتماد الفترة وتوزيع خصم السلف');await render()}catch(e){toast(friendlyError(e),'error')}return}if(a==='role-edit'){openRole(el);return}if(a==='roles-refresh'){await render();return}if(a==='reports-refresh'||a==='audit-refresh'){await render();return}if(a==='user-new'){openUser();return}if(a.endsWith('-action'))toast('سيتم تفعيل هذا القسم في مرحلته مع ربطه بالحسابات والمخزون والصلاحيات.')}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el).catch(err=>toast(friendlyError(err),'error'))}});
document.addEventListener('input',e=>{if(e.target.id==='product-search'){const q=e.target.value.trim().toLowerCase();document.querySelectorAll('#products-body tr[data-search-text]').forEach(r=>r.hidden=!r.dataset.searchText.toLowerCase().includes(q))}});
document.addEventListener('change',e=>{if(e.target.matches('[data-sale-product]')){const line=e.target.closest('.sale-line'),product=e.target.value,duplicate=[...document.querySelectorAll('.sale-line')].find(x=>x!==line&&x.querySelector('[data-sale-product]')?.value===product&&product);if(duplicate){const q=duplicate.querySelector('[data-sale-qty]'),cur=line.querySelector('[data-sale-qty]');q.value=Number(q.value||0)+Number(cur.value||0);line.remove()}else{const o=e.target.selectedOptions[0];line.querySelector('[data-sale-price]').value=o?.dataset.price||0}updateSaleTotals()}if(e.target.closest('#sale-form'))updateSaleTotals()});
