document.addEventListener('submit',async e=>{if(e.target.id!=='payroll-form')return;e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));try{await dbRpc('prepare_payroll_period',{p_name:d.name,p_from:d.from,p_to:d.to});hideModal('payroll-modal');toast('تم تجهيز فترة المرتبات');await render()}catch(err){toast(friendlyError(err),'error')}});
document.addEventListener('submit',async e=>{if(e.target.id==='sale-payment-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await dbRpc('add_sale_payment',{p_sale_id:d.sale_id,p_amount:Number(d.amount||0),p_payment_method:d.method,p_cash_register_id:d.cash_id||null,p_bank_id:d.bank_id||null,p_reference:d.reference||null});hideModal('sale-payment-modal');toast('تم تسجيل الدفعة وتحديث المتبقي');await render()}catch(err){toast(friendlyError(err),'error')}}});
document.addEventListener('submit',async e=>{if(e.target.id!=='sale-form')return;e.preventDefault();const f=e.target;try{const items=[...f.querySelectorAll('.sale-line')].map(l=>({product_id:l.querySelector('[data-sale-product]').value,quantity:Number(l.querySelector('[data-sale-qty]').value),unit_price:Number(l.querySelector('[data-sale-price]').value)})).filter(x=>x.product_id&&x.quantity>0);if(!items.length)throw new Error('أضف منتجًا واحدًا على الأقل');const total=updateSaleTotals(),paid=Number(f.querySelector('[name="paid_amount"]').value||0),method=f.querySelector('[name="payment_method"]').value;await dbRpc('create_sale_draft',{p_invoice_type:f.querySelector('[name="invoice_type"]').value,p_customer_name:f.querySelector('[name="customer_name"]').value||'عميل عادي',p_customer_id:null,p_warehouse_id:f.querySelector('[name="warehouse_id"]').value,p_items:items,p_discount_type:f.querySelector('[name="discount_type"]').value,p_discount_value:Number(f.querySelector('[name="discount_value"]').value||0),p_crafting_fee:Number(f.querySelector('[name="crafting_fee"]').value||0),p_vat_enabled:f.querySelector('[name="vat_enabled"]').checked,p_vat_rate:Number(f.querySelector('[name="vat_rate"]').value||0),p_payments:paid>0?[{amount:paid,payment_method:method,cash_register_id:f.querySelector('[name="cash_register_id"]').value||null,bank_id:f.querySelector('[name="bank_id"]').value||null}]:[],p_notes:f.querySelector('[name="notes"]').value||null});hideModal('sale-modal');toast(`تم حفظ الفاتورة كمسودة بقيمة ${money(total)}`);await render()}catch(err){toast(friendlyError(err),'error')}});
document.addEventListener('submit',async e=>{if(e.target.id!=='product-form')return;e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));try{const args={p_name:d.name,p_category:d.category||null,p_unit:d.unit||null,p_cost_price:Number(d.cost_price||0),p_sale_price:Number(d.sale_price||0),p_minimum_stock:Number(d.minimum_stock||0),p_notes:d.notes||null,p_custom_fields:customFieldsFromForm(f)};if(d.id){args.p_id=d.id;await dbRpc('update_product',args)}else await dbRpc('create_product',args);hideModal('product-modal');toast(d.id?'تم تعديل المنتج وتسجيل التغيير':'تم حفظ المنتج وإتاحة استخدامه في الأقسام');await render()}catch(err){toast(friendlyError(err),'error')}});document.addEventListener('change',async e=>{if(e.target.matches('[data-employee-status]')&&e.target.value){try{await dbRpc('set_employee_status',{p_employee_id:e.target.dataset.id,p_status:e.target.value});toast('تم تغيير حالة العامل');await render()}catch(err){toast(friendlyError(err),'error')}}});
document.addEventListener('submit',async e=>{if(e.target.id==='role-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await dbRpc('update_role_controls',{p_role_id:d.role_id,p_data_scope:d.data_scope,p_cash_visibility:e.target.cash_visibility.checked,p_can_cash_in:e.target.can_cash_in.checked,p_can_cash_out:e.target.can_cash_out.checked,p_can_transfer:e.target.can_transfer.checked,p_can_count:e.target.can_count.checked,p_can_approve:e.target.can_approve.checked,p_spend_limit:d.spend_limit?Number(d.spend_limit):null,p_discount_limit:d.discount_limit?Number(d.discount_limit):null,p_transfer_limit:d.transfer_limit?Number(d.transfer_limit):null,p_adjustment_limit:d.adjustment_limit?Number(d.adjustment_limit):null});hideModal('role-modal');toast('تم حفظ ضوابط الدور');await render()}catch(err){toast(friendlyError(err),'error')}}});
document.addEventListener('submit',async e=>{if(e.target.id==='user-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await dbFunction('admin-create-user',{action:'create',email:d.email,full_name:d.full_name,role_code:d.role,password:d.password});hideModal('user-modal');toast('تم إنشاء المستخدم وربطه بالدور');await render()}catch(err){toast(friendlyError(err),'error')}}});
document.addEventListener('submit',async e=>{if(e.target.id==='factory-settings-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const next={...appCfg,factoryName:d.factory_name,currency:d.currency,vatRate:Number(d.vat_rate||0)};await dbRpc('save_factory_settings',{p_factory_name:d.factory_name,p_currency:d.currency,p_vat_rate:Number(d.vat_rate||0)});localStorage.setItem(appCfg.settingsKey,JSON.stringify(next));Object.assign(appCfg,next);toast('تم حفظ إعدادات المصنع مركزيًا');await render()}if(e.target.id==='password-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.password!==d.confirm){toast('كلمتا المرور غير متطابقتين','error');return}try{const{error}=await db.auth.updateUser({password:d.password});if(error)throw error;toast('تم تغيير كلمة المرور بنجاح');e.target.reset()}catch(err){toast(friendlyError(err),'error')}}});
window.addEventListener('hashchange',render);window.addEventListener('online',updateConnection);window.addEventListener('offline',updateConnection);if(db)db.auth.onAuthStateChange(()=>setTimeout(render,0));render();
